add('Reaction of Hexaaquacopper (II) Ions with Carbonate Ions','کاربونیٹ آئنوں سے ہیکسا ایکوا کاپر(II) آئنوں کا تعامل','له کاربونېټ ایونونو سره د هېکسا اکوا مسو(II) ایونونو تعامل','heading')
add('The hexaaquacopper (II) ions are not acidic enough to release CO₂ from carbonates.','ہیکسا ایکوا کاپر(II) آئن اتنے تیزابی نہیں کہ کاربونیٹس سے CO₂ خارج کریں۔','هېکسا اکوا مسو(II) ایونونه دومره اسیدي نه دي چې له کاربونېټونو CO₂ خوشې کړي.')
add('In these cases precipitation of metal carbonate takes place and gives rise to the following reaction.','ان صورتوں میں دھاتی کاربونیٹ کا رسوب بنتا ہے اور یہ تعامل ہوتا ہے۔','په دې حالتونو کې د فلزي کاربونېټ رسوب جوړېږي او لاندې تعامل رامنځته کېږي.')
add('Cu²⁺(aq) + CO₃²⁻(aq) → CuCO₃(s)','Cu²⁺(aq) + CO₃²⁻(aq) → CuCO₃(s)','Cu²⁺(aq) + CO₃²⁻(aq) → CuCO₃(s)','equation')
